"""SQLite access and migrations. Part of the scaffold: agents do not edit this file."""

from __future__ import annotations

import os
import sqlite3
from collections.abc import Iterator
from pathlib import Path

MIGRATIONS_DIR = Path(__file__).parent / "migrations"


def db_path() -> str:
    return os.environ.get("TESSERA_DB", "app.db")


def connect() -> sqlite3.Connection:
    conn = sqlite3.connect(db_path(), check_same_thread=False)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    return conn


def get_conn() -> Iterator[sqlite3.Connection]:
    """FastAPI dependency: one connection per request. Call conn.commit() after writes."""
    conn = connect()
    try:
        yield conn
    finally:
        conn.close()


def run_migrations() -> list[str]:
    """Apply every app/migrations/*.sql file once, in filename order. Returns the names applied."""
    conn = connect()
    applied: list[str] = []
    try:
        conn.execute("CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY)")
        done = {r["name"] for r in conn.execute("SELECT name FROM schema_migrations")}
        for path in sorted(MIGRATIONS_DIR.glob("*.sql")):
            if path.name in done:
                continue
            conn.executescript(path.read_text())
            conn.execute("INSERT INTO schema_migrations (name) VALUES (?)", (path.name,))
            conn.commit()
            applied.append(path.name)
    finally:
        conn.close()
    return applied
